// This file is generated by AI.

// 全项目唯一的模态框外壳。
//
// 为什么要有它: 之前每个对话框各写一套 (有的用 Fluent UI 的 `Dialog`, 有的自绘),
// 于是宽度、标题字号、内边距、按钮顺序、是否随内容缩放全都不同 —— 同一件事在不同
// 对话框里的交互都不一样。这里把结构定死: 遮罩 + 固定尺寸的面板 + 标题栏 + 可滚动
// 主体 + 底部操作栏。所有对话框只提供内容, 不再各自决定外观。
//
// 尺寸**固定**(不随内容自动缩放): `size` 决定宽高, 内容超出时由主体内部滚动。
// 这一点是刻意的 —— 弹窗随内容忽大忽小会让人每次都要重新找按钮在哪里。
//
// 不使用 portal: 与项目其余弹层一致, 避免 WebView 中的定位/动画异常。

import { useEffect, useRef, type ReactNode } from 'react';

export type DialogSize = 'small' | 'medium' | 'large';

interface Props {
  title: string;
  /** 标题下方的一行说明 (可选) */
  description?: ReactNode;
  size?: DialogSize;
  /** 固定高度 (默认按 size); 传 'auto' 表示高度随内容 (仅用于极短的信息框) */
  height?: number | 'auto';
  /** 紧凑模式: 主体不分段滚动, 由内容自行填满 (用于内部已有滚动列表的对话框) */
  compact?: boolean;
  /** 无内边距模式: 主体不加内边距, 由内容自己排布 (用于左右分栏这类自定义布局) */
  flush?: boolean;
  /** 追加到面板上的类名 (用于给个别对话框加尺寸之外的样式) */
  className?: string;
  /** 标题栏右侧的补充信息 (如当前分支) */
  titleExtra?: ReactNode;
  /** 底部操作区左侧的次要内容 (如"导出角色"), 主操作与取消放右侧 */
  footerLeading?: ReactNode;
  /** 底部操作区的按钮 */
  footer?: ReactNode;
  /** 点击遮罩是否关闭 (默认关闭; 只有会丢失正在编辑内容的对话框才显式设为 false) */
  closeOnBackdrop?: boolean;
  onClose: () => void;
  children: ReactNode;
}

export function AppDialog({
  title,
  description,
  size = 'medium',
  height,
  compact = false,
  flush = false,
  className,
  titleExtra,
  footerLeading,
  footer,
  closeOnBackdrop = true,
  onClose,
  children,
}: Props) {
  const surfaceRef = useRef<HTMLDivElement>(null);

  /*
   * Esc 关闭 (与自绘对话框一致; 不监听输入法组合键)。
   *
   * 对话框可以不使用 portal 地**嵌套** (例如「选择参考音频」里再打开「添加参考音频」),
   * 而每个实例都在 window 上监听按键 —— 不做判断的话一次 Esc 会把整叠对话框一起关掉。
   * 判据用 DOM 包含关系而不是"打开顺序栈": 谁里面还有别的对话框, 谁就不是最上层。
   */
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Escape' || event.isComposing) return;
      if (surfaceRef.current?.querySelector('.modal-surface')) return;
      onClose();
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [onClose]);

  const style = height === undefined || height === 'auto' ? undefined : { height };

  return (
    <div className="modal-backdrop" onClick={closeOnBackdrop ? onClose : undefined}>
      <div
        ref={surfaceRef}
        className={`modal-surface dialog-surface dialog-${size}${compact ? ' dialog-compact' : ''}${
          flush ? ' dialog-flush' : ''
        }${className ? ` ${className}` : ''}`}
        style={style}
        role="dialog"
        aria-modal="true"
        aria-label={title}
        onClick={(event) => event.stopPropagation()}
      >
        <header className="dialog-head">
          <h2 className="dialog-title">{title}</h2>
          {titleExtra ? <div className="dialog-title-extra">{titleExtra}</div> : null}
          {description ? <p className="dialog-description">{description}</p> : null}
        </header>

        <div className="dialog-body">{children}</div>

        <footer className="dialog-foot">
          {footerLeading ? <div className="dialog-foot-leading">{footerLeading}</div> : null}
          <div className="dialog-foot-actions">{footer}</div>
        </footer>
      </div>
    </div>
  );
}
